export fn jaro_similarity(v:[*]const i64,n:usize)f64{if(n<2 or n>66)return -1.0e300;if(v[0]<0 or v[0]>32)return -1.0e300;const n1:usize=@intCast(v[0]);const p=1+n1;if(p>=n)return -1.0e300;if(v[p]<0 or v[p]>32)return -1.0e300;const n2:usize=@intCast(v[p]);if(n1<n2 or n!=p+1+n2)return -1.0e300;for(0..n1)|i|{if(v[1+i]<0 or v[1+i]>127)return -1.0e300;}for(0..n2)|i|{if(v[p+1+i]<0 or v[p+1+i]>127)return -1.0e300;}var equal=n1==n2;for(0..n1)|i|{if(v[1+i]!=v[p+1+i])equal=false;}if(equal)return 1.0;if(n2==0)return 0.0;const radius=if(n1/2>0)n1/2-1 else 0;var m1:[32]bool=@splat(false);var m2:[32]bool=@splat(false);var matches:i64=0;for(0..n1)|i|{const start=if(i>radius)i-radius else 0;const finish=@min(i+radius,n2-1);if(start<=finish){for(start..finish+1)|j|{if(v[1+i]==v[p+1+j] and !m2[j]){matches+=1;m1[i]=true;m2[j]=true;break;}}}}if(matches==0)return 0.0;var trans:i64=0;var j:usize=0;for(0..n1)|i|{if(m1[i]){while(!m2[j]){j+=1;}if(v[1+i]!=v[p+1+j])trans+=1;j+=1;}}trans=@divTrunc(trans,2);return (@as(f64,@floatFromInt(matches))/@as(f64,@floatFromInt(n1))+@as(f64,@floatFromInt(matches))/@as(f64,@floatFromInt(n2))+@as(f64,@floatFromInt(matches-trans))/@as(f64,@floatFromInt(matches)))/3.0;}
